// Parse the incoming Telegram message for a project query.
const raw = $json.message?.text || '';
const msg = raw.trim();
const chatId = String($json.message?.chat?.id || '');

// Match patterns like:
//   "where did I stop on <project>"
//   "where am I on <project>"
//   "status on <project>"
//   "status of <project>"
const patterns = [
  /where\s+(?:did\s+I\s+(?:stop|leave\s+off)|am\s+I)\s+on\s+(.+)/i,
  /status\s+(?:on|of|for)\s+(.+)/i,
  /(?:update|progress)\s+(?:on|for)\s+(.+)/i
];

let project = null;
for (const re of patterns) {
  const m = msg.match(re);
  if (m) {
    project = m[1].trim().replace(/[?!.]+$/, '').trim();
    break;
  }
}

return [{
  json: {
    project: project,
    hasProject: !!project,
    chatId: chatId,
    rawMessage: msg
  }
}];

// Filter rows to the requested project (case-insensitive) and
// format as chronological readable text for the LLM.
const projectName = $('Parse Project Name').item.json.project;
const rows = $input.all()
  .map(i => i.json)
  .filter(r => (r['Project'] || '').trim().toLowerCase() === projectName.toLowerCase())
  .sort((a, b) => new Date(a['Date']) - new Date(b['Date']));

if (rows.length === 0) {
  return [{
    json: {
      empty: true,
      chatId: $('Parse Project Name').item.json.chatId,
      projectName
    }
  }];
}

let text = `Full log history for project: ${projectName}\n\n`;
for (const r of rows) {
  text += `[${r['Date']}]\n`;
  text += `  What I did: ${r['What I did'] || 'N/A'}\n`;
  text += `  Blocker / Next step: ${r['Blocker/Next step'] || 'N/A'}\n`;
  text += `  Status: ${r['Status'] || 'N/A'}\n\n`;
}

return [{
  json: {
    empty: false,
    formattedText: text.trim(),
    chatId: $('Parse Project Name').item.json.chatId,
    projectName
  }
}];
